mkuse!{use rustc_data_structures :: sync :: { self , AppendOnlyIndexVec , FreezeLock } ;}
mkuse!{use rustc_hir :: attrs :: { CfgEntry , NativeLibKind , PeImportNameType } ;}
mkuse!{use rustc_hir :: def_id :: { CrateNum , DefId , LOCAL_CRATE , LocalDefId , StableCrateId , StableCrateIdMap , } ;}
mkuse!{use rustc_hir :: definitions :: { DefKey , DefPath , DefPathHash , Definitions } ;}
mkuse!{use rustc_macros :: { Decodable , Encodable , HashStable_Generic } ;}
mkuse!{use rustc_span :: { Span , Symbol } ;}
mkuse!{use crate :: search_paths :: PathKind ;}
mkitem!{mkstruct!{# [doc = " Where a crate came from on the local filesystem. One of these three options"] # [doc = " must be non-None."] # [derive (PartialEq , Clone , Debug , HashStable_Generic , Encodable , Decodable)] pub struct CrateSource { pub dylib : Option < (PathBuf , PathKind) > , pub rlib : Option < (PathBuf , PathKind) > , pub rmeta : Option < (PathBuf , PathKind) > , pub sdylib_interface : Option < (PathBuf , PathKind) > , }}}
mkitem!{mkimpl!{impl CrateSource { # [inline] pub fn paths (& self) -> impl Iterator < Item = & PathBuf > { self . dylib . iter () . chain (self . rlib . iter ()) . chain (self . rmeta . iter ()) . map (| p | & p . 0) } }}}
mkitem!{mkenum!{# [derive (Encodable , Decodable , Copy , Clone , Ord , PartialOrd , Eq , PartialEq , Debug)] # [derive (HashStable_Generic)] pub enum CrateDepKind { # [doc = " A dependency that is only used for its macros."] MacrosOnly , # [doc = " A dependency that is always injected into the dependency list and so"] # [doc = " doesn't need to be linked to an rlib, e.g., the injected panic runtime."] Implicit , # [doc = " A dependency that is required by an rlib version of this crate."] # [doc = " Ordinary `extern crate`s result in `Explicit` dependencies."] Explicit , }}}
mkitem!{mkimpl!{impl CrateDepKind { # [inline] pub fn macros_only (self) -> bool { match self { CrateDepKind :: MacrosOnly => true , CrateDepKind :: Implicit | CrateDepKind :: Explicit => false , } } }}}
mkitem!{mkenum!{# [derive (Copy , Debug , PartialEq , Clone , Encodable , Decodable , HashStable_Generic)] pub enum LinkagePreference { RequireDynamic , RequireStatic , }}}
mkitem!{mkstruct!{# [derive (Debug , Encodable , Decodable , HashStable_Generic)] pub struct NativeLib { pub kind : NativeLibKind , pub name : Symbol , # [doc = " If packed_bundled_libs enabled, actual filename of library is stored."] pub filename : Option < Symbol > , pub cfg : Option < CfgEntry > , pub foreign_module : Option < DefId > , pub verbatim : Option < bool > , pub dll_imports : Vec < DllImport > , }}}
mkitem!{mkimpl!{impl NativeLib { pub fn has_modifiers (& self) -> bool { self . verbatim . is_some () || self . kind . has_modifiers () } pub fn wasm_import_module (& self) -> Option < Symbol > { if self . kind == NativeLibKind :: WasmImportModule { Some (self . name) } else { None } } }}}
mkitem!{mkstruct!{# [derive (Clone , Debug , Encodable , Decodable , HashStable_Generic)] pub struct DllImport { pub name : Symbol , pub import_name_type : Option < PeImportNameType > , # [doc = " Calling convention for the function."] # [doc = ""] # [doc = " On x86_64, this is always `DllCallingConvention::C`; on i686, it can be any"] # [doc = " of the values, and we use `DllCallingConvention::C` to represent `\"cdecl\"`."] pub calling_convention : DllCallingConvention , # [doc = " Span of import's \"extern\" declaration; used for diagnostics."] pub span : Span , # [doc = " Is this for a function (rather than a static variable)."] pub is_fn : bool , }}}
mkitem!{mkimpl!{impl DllImport { pub fn ordinal (& self) -> Option < u16 > { if let Some (PeImportNameType :: Ordinal (ordinal)) = self . import_name_type { Some (ordinal) } else { None } } pub fn is_missing_decorations (& self) -> bool { self . import_name_type == Some (PeImportNameType :: Undecorated) || self . import_name_type == Some (PeImportNameType :: NoPrefix) } }}}
mkitem!{mkenum!{# [doc = " Calling convention for a function defined in an external library."] # [doc = ""] # [doc = " The usize value, where present, indicates the size of the function's argument list"] # [doc = " in bytes."] # [derive (Clone , PartialEq , Debug , Encodable , Decodable , HashStable_Generic)] pub enum DllCallingConvention { C , Stdcall (usize) , Fastcall (usize) , Vectorcall (usize) , }}}
mkitem!{mkstruct!{# [derive (Clone , Encodable , Decodable , HashStable_Generic , Debug)] pub struct ForeignModule { pub foreign_items : Vec < DefId > , pub def_id : DefId , pub abi : ExternAbi , }}}
mkitem!{mkstruct!{# [derive (Copy , Clone , Debug , HashStable_Generic)] pub struct ExternCrate { pub src : ExternCrateSource , # [doc = " span of the extern crate that caused this to be loaded"] pub span : Span , # [doc = " Number of links to reach the extern;"] # [doc = " used to select the extern with the shortest path"] pub path_len : usize , # [doc = " Crate that depends on this crate"] pub dependency_of : CrateNum , }}}
mkitem!{mkimpl!{impl ExternCrate { # [doc = " If true, then this crate is the crate named by the extern"] # [doc = " crate referenced above. If false, then this crate is a dep"] # [doc = " of the crate."] # [inline] pub fn is_direct (& self) -> bool { self . dependency_of == LOCAL_CRATE } # [inline] pub fn rank (& self) -> impl PartialOrd { (self . is_direct () , ! self . path_len) } }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug , HashStable_Generic)] pub enum ExternCrateSource { # [doc = " Crate is loaded by `extern crate`."] Extern (# [doc = " def_id of the item in the current crate that caused"] # [doc = " this crate to be loaded; note that there could be multiple"] # [doc = " such ids"] DefId ,) , # [doc = " Crate is implicitly loaded by a path resolving through extern prelude."] Path , }}}
mkitem!{mktrait!{# [doc = " A store of Rust crates, through which their metadata can be accessed."] # [doc = ""] # [doc = " Note that this trait should probably not be expanding today. All new"] # [doc = " functionality should be driven through queries instead!"] # [doc = ""] # [doc = " If you find a method on this trait named `{name}_untracked` it signifies"] # [doc = " that it's *not* tracked for dependency information throughout compilation"] # [doc = " (it'd break incremental compilation) and should only be called pre-HIR (e.g."] # [doc = " during resolve)"] pub trait CrateStore : std :: fmt :: Debug { fn as_any (& self) -> & dyn Any ; fn untracked_as_any (& mut self) -> & mut dyn Any ; fn def_key (& self , def : DefId) -> DefKey ; fn def_path (& self , def : DefId) -> DefPath ; fn def_path_hash (& self , def : DefId) -> DefPathHash ; fn crate_name (& self , cnum : CrateNum) -> Symbol ; fn stable_crate_id (& self , cnum : CrateNum) -> StableCrateId ; }}}
mkitem!{pub type CrateStoreDyn = dyn CrateStore + sync :: DynSync + sync :: DynSend ;}
mkitem!{mkstruct!{pub struct Untracked { pub cstore : FreezeLock < Box < CrateStoreDyn > > , # [doc = " Reference span for definitions."] pub source_span : AppendOnlyIndexVec < LocalDefId , Span > , pub definitions : FreezeLock < Definitions > , # [doc = " The interned [StableCrateId]s."] pub stable_crate_ids : FreezeLock < StableCrateIdMap > , }}}